reference.MergeSorted:
r := [];
var i := 0;
var j := 0;
var pa: seq<int> := [];
var pb: seq<int> := [];
while i < |a| || j < |b|
  invariant 0 <= i <= |a| && 0 <= j <= |b|
  invariant |pa| == i && |pb| == j
  invariant forall k :: 0 <= k < i ==> pa[k] == a[k]
  invariant forall k :: 0 <= k < j ==> pb[k] == b[k]
  invariant |r| == i + j
  invariant multiset(r) == multiset(pa) + multiset(pb)
  invariant forall k, l :: 0 <= k < l < |r| ==> r[k] <= r[l]
  invariant forall k :: 0 <= k < |r| && i < |a| ==> r[k] <= a[i]
  invariant forall k :: 0 <= k < |r| && j < |b| ==> r[k] <= b[j]
  decreases |a| + |b| - i - j
{
  if j == |b| || (i < |a| && a[i] <= b[j]) {
    r := r + [a[i]];
    pa := pa + [a[i]];
    i := i + 1;
  } else {
    r := r + [b[j]];
    pb := pb + [b[j]];
    j := j + 1;
  }
}
assert pa == a;
assert pb == b;

bodies.MergeSorted:
r := [];
var i := 0;
var j := 0;
while i + j < |a| + |b| - 1
  invariant 0 <= i <= |a| && 0 <= j <= |b|
  decreases |a| + |b| - i - j
{
  if j == |b| || (i < |a| && a[i] >= b[j]) {
    r := r + [a[i]];
    i := i + 1;
  } else {
    r := r + [b[j]];
    j := j + 1;
  }
}
